let shoeViewer={};
const LINQ_MESH={"vertices":"","indices":"","count":120000};
function initShoe(el){const canvas=el.querySelector('canvas');const gl=canvas.getContext('webgl',{alpha:true,antialias:true});if(!gl||!gl.getExtension('OES_element_index_uint')){initShoeCPU(el,canvas);return}const vs=`attribute vec3 p;attribute vec3 n;uniform vec2 rot;uniform float aspect;uniform float zoom;varying vec3 normal;vec3 turn(vec3 v){float a=rot.x,b=rot.y;v=vec3(v.x,cos(a)*v.y-sin(a)*v.z,sin(a)*v.y+cos(a)*v.z);return vec3(cos(b)*v.x+sin(b)*v.z,v.y,-sin(b)*v.x+cos(b)*v.z);}void main(){vec3 v=turn(p);normal=turn(n);gl_Position=vec4(v.x*zoom/aspect,v.y*zoom,-v.z*.2,1.);}`;const fs=`precision mediump float;varying vec3 normal;void main(){vec3 n=normalize(normal);if(!gl_FrontFacing)n=-n;float key=max(dot(n,normalize(vec3(-.4,1.,1.5))),0.);float fill=max(dot(n,normalize(vec3(1.,.1,.2))),0.);float rim=pow(1.-abs(n.z),3.);vec3 color=vec3(.76,.77,.72)*(.38+.62*key)+vec3(.12,.15,.16)*fill+vec3(.14,.12,.08)*rim;gl_FragColor=vec4(color,1.);}`;function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s}const pr=gl.createProgram();gl.attachShader(pr,shader(gl.VERTEX_SHADER,vs));gl.attachShader(pr,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(pr);gl.useProgram(pr);const bytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));const vb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,vb);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(bytes(LINQ_MESH.vertices).buffer),gl.STATIC_DRAW);for(const [name,offset] of [['p',0],['n',12]]){const i=gl.getAttribLocation(pr,name);gl.enableVertexAttribArray(i);gl.vertexAttribPointer(i,3,gl.FLOAT,false,24,offset)}const ib=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint32Array(bytes(LINQ_MESH.indices).buffer),gl.STATIC_DRAW);const ur=gl.getUniformLocation(pr,'rot'),ua=gl.getUniformLocation(pr,'aspect'),uz=gl.getUniformLocation(pr,'zoom');let rx=.45,ry=-.35,zoom=1.55,drag=null;function draw(){const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;const d=Math.min(devicePixelRatio||1,2),w=Math.round(r.width*d),h=Math.round(r.height*d);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}gl.viewport(0,0,w,h);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);gl.uniform2f(ur,rx,ry);gl.uniform1f(ua,w/h);gl.uniform1f(uz,zoom);gl.drawElements(gl.TRIANGLES,LINQ_MESH.count,gl.UNSIGNED_INT,0);canvas.dataset.rotation=rx.toFixed(2)+','+ry.toFixed(2)}shoeViewer.resize=draw;new ResizeObserver(draw).observe(canvas);canvas.addEventListener('pointerdown',e=>{e.stopPropagation();canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,rx,ry};canvas.focus({preventScroll:true})});canvas.addEventListener('pointermove',e=>{if(!drag)return;ry=drag.ry+(e.clientX-drag.x)*.008;rx=drag.rx+(e.clientY-drag.y)*.008;draw()});['pointerup','pointercancel'].forEach(t=>canvas.addEventListener(t,()=>drag=null));canvas.addEventListener('wheel',e=>{e.preventDefault();e.stopPropagation();zoom=Math.max(.8,Math.min(2.2,zoom-e.deltaY*.002));draw()},{passive:false});canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key)){e.preventDefault();e.stopPropagation();ry+=(e.key==='ArrowRight'?.12:e.key==='ArrowLeft'?-.12:0);rx+=(e.key==='ArrowDown'?.12:e.key==='ArrowUp'?-.12:0);zoom=Math.max(.8,Math.min(2.2,zoom+(e.key==='+'?.1:e.key==='-'?-.1:0)));draw()}});el.querySelector('[data-shoe-reset]').onclick=()=>{rx=.45;ry=-.35;zoom=1.55;draw()};draw()}
function initShoeCPU(el,old){const canvas=document.createElement('canvas');canvas.tabIndex=0;canvas.setAttribute('aria-label','LINQ V9 footwear. Drag or use arrow keys to rotate.');old.replaceWith(canvas);const c=canvas.getContext('2d');const decode=s=>Uint8Array.from(atob(s),v=>v.charCodeAt(0));const mesh=LINQ_MESH,v=new Float32Array(decode(mesh.vertices).buffer),idx=new Uint32Array(decode(mesh.indices).buffer);let rx=.45,ry=-.35,zoom=1.55,drag=null,scheduled=false;const count=v.length/6,px=new Float32Array(count),py=new Float32Array(count),pz=new Float32Array(count),light=new Float32Array(count),order=Array.from({length:idx.length/3},(_,i)=>i);function draw(){scheduled=false;const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const d=Math.min(devicePixelRatio||1,1.5),w=rect.width,h=rect.height;canvas.width=w*d;canvas.height=h*d;c.setTransform(d,0,0,d,0,0);c.clearRect(0,0,w,h);const ca=Math.cos(rx),sa=Math.sin(rx),cb=Math.cos(ry),sb=Math.sin(ry),scale=h*zoom/2;for(let i=0;i<count;i++){const j=i*6,x=v[j],y=ca*v[j+1]-sa*v[j+2],z=sa*v[j+1]+ca*v[j+2];px[i]=w/2+(cb*x+sb*z)*scale;py[i]=h/2-y*scale;pz[i]=-sb*x+cb*z;const nx=v[j+3],ny=ca*v[j+4]-sa*v[j+5],nz=sa*v[j+4]+ca*v[j+5];light[i]=Math.abs((-.4*(cb*nx+sb*nz)+ny+1.5*(-sb*nx+cb*nz))/1.85)}order.sort((a,b)=>(pz[idx[a*3]]+pz[idx[a*3+1]]+pz[idx[a*3+2]])-(pz[idx[b*3]]+pz[idx[b*3+1]]+pz[idx[b*3+2]]));for(const t of order){const a=idx[t*3],b=idx[t*3+1],e=idx[t*3+2];const shade=Math.round(105+125*(light[a]+light[b]+light[e])/3);c.fillStyle=`rgb(${shade},${shade+2},${shade-6})`;c.beginPath();c.moveTo(px[a],py[a]);c.lineTo(px[b],py[b]);c.lineTo(px[e],py[e]);c.closePath();c.fill()}canvas.dataset.rotation=rx.toFixed(2)+','+ry.toFixed(2);canvas.dataset.renderer='software-3d'}function queue(){if(!scheduled){scheduled=true;requestAnimationFrame(draw)}}shoeViewer.resize=queue;new ResizeObserver(queue).observe(canvas);canvas.addEventListener('pointerdown',e=>{e.stopPropagation();canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,rx,ry};canvas.focus({preventScroll:true})});canvas.addEventListener('pointermove',e=>{if(!drag)return;ry=drag.ry+(e.clientX-drag.x)*.008;rx=drag.rx+(e.clientY-drag.y)*.008;queue()});['pointerup','pointercancel'].forEach(t=>canvas.addEventListener(t,()=>drag=null));canvas.addEventListener('wheel',e=>{e.preventDefault();e.stopPropagation();zoom=Math.max(.8,Math.min(2.2,zoom-e.deltaY*.002));queue()},{passive:false});canvas.addEventListener('keydown',e=>{if(e.key.startsWith('Arrow')||['+','-'].includes(e.key)){e.preventDefault();e.stopPropagation();ry+=e.key==='ArrowRight'?.12:e.key==='ArrowLeft'?-.12:0;rx+=e.key==='ArrowDown'?.12:e.key==='ArrowUp'?-.12:0;zoom=Math.max(.8,Math.min(2.2,zoom+(e.key==='+'?.1:e.key==='-'?-.1:0)));queue()}});el.querySelector('[data-shoe-reset]').onclick=()=>{rx=.45;ry=-.35;zoom=1.55;queue()};queue()}


initShoe(document.getElementById("shoe-viewer"));
